function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.businessLogic || {};

  // 計算結果を格納する配列
  let calculationResults = [];

  // 店舗データを取得してセレクトボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのテーブルインデックス
      const storeSelect = container.querySelector('#select-store');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗データの取得に失敗しました');
    }
  }

  // 商品データを取得してセレクトボックスに設定
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタのテーブルインデックス
      const productSelect = container.querySelector('#select-product');
      productSelect.innerHTML = '<option value="">商品を選択してください</option>';

      if (products) {
        products.forEach(product => {
          const option = document.createElement('option');
          option.value = product.id;
          option.textContent = `${product.商品名} (${product.商品コード})`;
          productSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error('商品データの取得に失敗しました');
    }
  }

  // 計算結果テーブルの再描画
  function renderCalculationResults(results) {
    const tbody = container.querySelector('#calculation-results');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>${result.安全在庫 || 0}</td>
        <td>${result.発注点 || 0}</td>
        <td>${result.推奨発注量 || 0}</td>
        <td>${result.計算日時 || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => {
        errorDiv.classList.add('hidden');
      }, 5000);
    }
  }

  // 需要予測結果表示
  function showPredictionResult(result) {
    const predictionDiv = container.querySelector('#prediction-result');
    if (predictionDiv) {
      predictionDiv.innerHTML = `
        <div style="color: var(--text);">
          <p><strong>予測需要量:</strong> ${result.予測需要量 || 0} 個</p>
          <p><strong>予測精度:</strong> ${result.予測精度 || 0}%</p>
          <p><strong>推奨発注量:</strong> ${result.推奨発注量 || 0} 個</p>
        </div>
      `;
    }
  }

  // バリデーション
  function validateInputs() {
    const productCode = container.querySelector('#input-product-code')?.value?.trim();
    const currentStock = parseInt(container.querySelector('#input-current-stock')?.value);
    const predictedDemand = parseInt(container.querySelector('#input-predicted-demand')?.value);
    const safetyStock = parseInt(container.querySelector('#input-safety-stock')?.value);
    const orderCycle = parseInt(container.querySelector('#input-order-cycle')?.value);
    const leadTime = parseInt(container.querySelector('#input-lead-time')?.value);

    if (!productCode) {
      showError('商品コードを入力してください');
      return false;
    }

    if (isNaN(currentStock) || currentStock < 0) {
      showError('現在在庫数は0以上の数値を入力してください');
      return false;
    }

    if (isNaN(predictedDemand) || predictedDemand < 0) {
      showError('予測需要量は0以上の数値を入力してください');
      return false;
    }

    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫は0以上の数値を入力してください');
      return false;
    }

    if (isNaN(orderCycle) || orderCycle <= 0) {
      showError('発注サイクルは1以上の数値を入力してください');
      return false;
    }

    if (isNaN(leadTime) || leadTime < 0) {
      showError('リードタイムは0以上の数値を入力してください');
      return false;
    }

    return true;
  }

  // 需要予測計算処理
  async function calculateDemandPrediction() {
    if (!validateInputs()) {
      return;
    }

    try {
      const storeId = container.querySelector('#select-store')?.value;
      const productCode = container.querySelector('#input-product-code')?.value?.trim();
      const currentStock = parseInt(container.querySelector('#input-current-stock')?.value);
      const safetyStock = parseInt(container.querySelector('#input-safety-stock')?.value);
      const orderCycle = parseInt(container.querySelector('#input-order-cycle')?.value);
      const leadTime = parseInt(container.querySelector('#input-lead-time')?.value);

      // 売上データを収集
      const salesData = await collectSalesData(storeId, productCode);

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct(salesData);

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData(productSalesData);

      // 天候データを収集
      const weatherData = await collectWeatherData(storeId);

      // イベントデータを収集
      const eventData = await collectEventData(storeId);

      // 季節データを収集
      const seasonalData = await collectSeasonalData();

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData(validProductData);

      // 需要予測量を計算（簡易的な計算）
      const baselineDemand = validProductData.reduce((sum, data) => sum + (data.売上数量 || 0), 0) / validProductData.length || 0;
      const weatherAdjustment = weatherCorrelation.correlation * weatherCorrelation.impact || 0;
      const eventAdjustment = eventCorrelation.correlation * eventCorrelation.impact || 0;
      const seasonalAdjustment = seasonalCorrelation.correlation * seasonalCorrelation.impact || 0;

      const predictedDemand = Math.round(baselineDemand + weatherAdjustment + eventAdjustment + seasonalAdjustment);

      // 発注点計算
      const orderPoint = Math.round((predictedDemand * leadTime / orderCycle) + safetyStock);

      // 推奨発注量計算
      const recommendedOrderQuantity = Math.max(0, orderPoint - currentStock);

      // 予測精度計算（簡易的）
      const accuracy = Math.min(100, Math.max(0, 100 - Math.abs(historicalComparison.variance || 0) * 10));

      const result = {
        商品コード: productCode,
        現在在庫: currentStock,
        予測需要量: predictedDemand,
        安全在庫: safetyStock,
        発注点: orderPoint,
        推奨発注量: recommendedOrderQuantity,
        予測精度: Math.round(accuracy),
        計算日時: new Date().toLocaleString('ja-JP')
      };

      // 結果を表示
      showPredictionResult(result);

      // 計算結果を配列に追加
      calculationResults.unshift({
        id: Date.now(),
        ...result
      });

      // テーブルを更新
      renderCalculationResults(calculationResults);

      window.aivicNotify.success('需要予測計算が完了しました');

    } catch (error) {
      console.error('需要予測計算エラー:', error);
      window.aivicNotify.error('需要予測計算に失敗しました');
    }
  }

  // 一括計算処理
  async function calculateBulkPrediction() {
    try {
      const storeId = container.querySelector('#select-store')?.value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      // 商品一覧を取得
      const products = await window.aivicApi.list(2);

      if (!products || products.length === 0) {
        showError('商品データが見つかりません');
        return;
      }

      const results = [];

      for (const product of products) {
        try {
          // 各商品の売上データを収集
          const salesData = await collectSalesData(storeId, product.商品コード);
          const productSalesData = classifySalesDataByProduct(salesData);
          const validProductData = filterValidProductData(productSalesData);

          if (validProductData.length === 0) continue;

          // 簡易的な需要予測計算
          const baselineDemand = validProductData.reduce((sum, data) => sum + (data.売上数量 || 0), 0) / validProductData.length || 0;
          const predictedDemand = Math.round(baselineDemand);
          const safetyStock = Math.round(predictedDemand * 0.1); // 予測需要の10%を安全在庫とする
          const orderPoint = Math.round(predictedDemand + safetyStock);
          const currentStock = product.在庫数量 || 0;
          const recommendedOrderQuantity = Math.max(0, orderPoint - currentStock);

          results.push({
            id: `bulk_${product.id}_${Date.now()}`,
            商品名: product.商品名,
            商品コード: product.商品コード,
            現在在庫: currentStock,
            予測需要量: predictedDemand,
            安全在庫: safetyStock,
            発注点: orderPoint,
            推奨発注量: recommendedOrderQuantity,
            計算日時: new Date().toLocaleString('ja-JP')
          });
        } catch (error) {
          console.error(`商品 ${product.商品コード} の計算エラー:`, error);
        }
      }

      // 結果をマージして表示
      calculationResults = [...results, ...calculationResults];
      renderCalculationResults(calculationResults);

      window.aivicNotify.success(`${results.length}件の商品の需要予測計算が完了しました`);

    } catch (error) {
      console.error('一括計算エラー:', error);
      window.aivicNotify.error('一括計算に失敗しました');
    }
  }

  // 計算結果クリア
  function clearResults() {
    calculationResults = [];
    renderCalculationResults(calculationResults);

    const predictionDiv = container.querySelector('#prediction-result');
    if (predictionDiv) {
      predictionDiv.innerHTML = '';
    }

    window.aivicNotify.success('計算結果をクリアしました');
  }

  // 計算結果保存
  async function saveResults() {
    if (calculationResults.length === 0) {
      showError('保存する計算結果がありません');
      return;
    }

    try {
      for (const result of calculationResults) {
        await window.aivicApi.save(5, result); // 発注計算結果テーブルのインデックス
      }

      window.aivicNotify.success('計算結果を保存しました');
    } catch (error) {
      console.error('保存エラー:', error);
      window.aivicNotify.error('計算結果の保存に失敗しました');
    }
  }

  // イベントハンドラーの設定
  function setupEventHandlers() {
    // 計算実行ボタン
    const calculateBtn = container.querySelector('#btn-calculate');
    if (calculateBtn) {
      calculateBtn.addEventListener('click', calculateDemandPrediction);
    }

    // 一括計算ボタン
    const bulkCalculateBtn = container.querySelector('#btn-bulk-calculate');
    if (bulkCalculateBtn) {
      bulkCalculateBtn.addEventListener('click', calculateBulkPrediction);
    }

    // 結果クリアボタン
    const clearBtn = container.querySelector('#btn-clear-results');
    if (clearBtn) {
      clearBtn.addEventListener('click', clearResults);
    }

    // 結果保存ボタン
    const saveBtn = container.querySelector('#btn-save-results');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveResults);
    }

    // 詳細ボタンのイベント委譲
    const resultsTable = container.querySelector('#calculation-results');
    if (resultsTable) {
      resultsTable.addEventListener('click', (e) => {
        if (e.target.classList.contains('detail-btn')) {
          const resultId = e.target.getAttribute('data-id');
          const result = calculationResults.find(r => r.id == resultId);
          if (result) {
            showPredictionResult(result);
          }
        }
      });
    }

    // 商品選択時の自動入力
    const productSelect = container.querySelector('#select-product');
    if (productSelect) {
      productSelect.addEventListener('change', async (e) => {
        const productId = e.target.value;
        if (productId) {
          try {
            const products = await window.aivicApi.list(2);
            const selectedProduct = products.find(p => p.id == productId);
            if (selectedProduct) {
              const productCodeInput = container.querySelector('#input-product-code');
              const currentStockInput = container.querySelector('#input-current-stock');

              if (productCodeInput) {
                productCodeInput.value = selectedProduct.商品コード || '';
              }
              if (currentStockInput) {
                currentStockInput.value = selectedProduct.在庫数量 || 0;
              }
            }
          } catch (error) {
            console.error('商品情報取得エラー:', error);
          }
        }
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadProducts();
      setupEventHandlers();
      renderCalculationResults(calculationResults);
    } catch (error) {
      console.error('初期化エラー:', error);
      window.aivicNotify.error('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
